if(PHP_SAPI!=='cli'){http_response_code(404);exit;}
require dirname(__DIR__).'/app/qhse.php';require_once dirname(__DIR__).'/app/equipment-catalog.php';
$owner=uuid();$userId=uuid();$customer=uuid();$asset=uuid();$checks=0;$failed=false;
