foreach(rows("SELECT id FROM owners WHERE name='Certificate Fixture' AND email LIKE '%@example.invalid'") as $stale){$staleId=$stale['id'];db()->prepare('DELETE FROM qhse_reusable_values WHERE owner_id=?')->execute([$staleId]);db()->prepare('DELETE FROM equipment_statuses WHERE owner_id=?')->execute([$staleId]);db()->prepare('DELETE FROM user_scopes WHERE user_id IN (SELECT id FROM users WHERE owner_id=?)')->execute([$staleId]);db()->prepare('DELETE FROM units WHERE plant_id IN (SELECT id FROM plants WHERE site_id IN (SELECT id FROM sites WHERE space_id IN (SELECT id FROM spaces WHERE owner_id=?)))')->execute([$staleId]);db()->prepare('DELETE FROM plants WHERE site_id IN (SELECT id FROM sites WHERE space_id IN (SELECT id FROM spaces WHERE owner_id=?))')->execute([$staleId]);db()->prepare('DELETE FROM sites WHERE space_id IN (SELECT id FROM spaces WHERE owner_id=?)')->execute([$staleId]);db()->prepare('DELETE FROM spaces WHERE owner_id=?')->execute([$staleId]);db()->prepare('DELETE FROM users WHERE owner_id=?')->execute([$staleId]);db()->prepare('DELETE FROM owners WHERE id=?')->execute([$staleId]);}
try{
 db()->prepare("INSERT INTO owners(id,name,email,phone) VALUES(?,?,?,'0')")->execute([$owner,'Certificate Fixture',$owner.'@example.invalid']);
 db()->prepare("INSERT INTO users(id,owner_id,full_name,email,phone,password_hash,is_email_verified,role) VALUES(?,?,?,?,'0','unused',1,'OWNER_ADMIN')")->execute([$userId,$owner,'Quality Approver',$userId.'@example.invalid']);$user=rows('SELECT * FROM users WHERE id=?',[$userId])[0];$user['company_name']='Certificate Fixture';
 $unit=equipment_default_unit($user);equipment_seed_statuses($owner);
